package net.officefloor.hq.app.access;

import java.util.Arrays;
import java.util.Optional;

/**
 * What a user may do on a sheet: a clerk settles only within the clerk limit (above it the claim goes
 * PENDING), a steward settles anything and approves or rejects a PENDING claim; a viewer sees everything
 * and can change nothing.
 */
public enum Role {
    CLERK, STEWARD, VIEWER;

    /** The role as it is written: lower case. */
    public String key() {
        return name().toLowerCase();
    }

    public static Optional<Role> of(String key) {
        return Arrays.stream(values()).filter(r -> r.key().equals(key)).findFirst();
    }
}
    public record RoleView(String user, String role) {

        static RoleView of(SheetRole r) {
            return new RoleView(r.getUserName(), r.getRole().key());
        }
    }

    /**
     * The sheet's settings as shown, each dated one the value in force on the sheet's today; a limit is a
     * figure with two decimals, null for none; so is the floor;
     * the terms are a number of days, and so are the terms of grades A, B and C, null for a grade without
     * its own (it uses the sheet's); the late percent is a figure with two decimals; the policy date and
     * the period numbering from are dates (yyyy-mm-dd), null when blank; the grace days are a number of days, null
     * when blank (off); the cap is a figure with two
     * decimals, null for none; so are the proof threshold and the note threshold. Each entry of the permission matrix (open, settle,
     * void, reassign, close, reopen) is the roles that may take the action as written, comma separated; null
     * when blank (the standing rule). The entry date is a date (yyyy-mm-dd), null when blank (off). The grace
     * days of grades A, B and C are a number of days, null for a grade with none; the proof thresholds of
     * grades A, B and C are figures with two decimals, null for a grade with none (it uses the sheet's). The
     * pot is a figure with two decimals, null for none; it is not dated. The parent is the id of the parent
     * sheet, null for none; it is not dated. The fiscal start month is the month (1 to 12) the sheet's fiscal
     * year starts in; it is not dated. The alert threshold is a figure with two decimals, null when off; it is not dated.
     * The escalation gap is a number of days, null when off; it is not dated.
     * The review SLA is a number of days, null for none; it is not dated.
     * The rounding mode is half-up or half-even, null for none (the policy date decides); it is dated.
     * The proof kinds are a comma separated list of kinds (receipt, photo), null for none; they are not dated.
     */

